def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    i = 0

    while i < len(line):
        c = line[i]

        if in_quotes:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field.append(c)
                i += 1
        else:
            if c == '"':
                in_quotes = True
                i += 1
            elif c == ',':
                fields.append(''.join(field))
                field = []
                i += 1
            else:
                field.append(c)
                i += 1

    fields.append(''.join(field))
    return fields
